  function handleForm(form,callback){form.addEventListener('submit',async e=>{e.preventDefault();if(form.dataset.saving)return;const values=Object.fromEntries(new FormData(form));const button=form.querySelector('[type=submit]'),old=button.innerHTML;const controls=[...form.querySelectorAll('input,select,textarea,button')].map(el=>[el,el.disabled]);form.dataset.saving='true';form.setAttribute('aria-busy','true');controls.forEach(([el])=>el.disabled=true);button.textContent=B.t("ui.shared.56a2285c5b","Saving…");try{await callback(values);}catch(err){if(form.isConnected)errorBox(form,err.message);else toast(err.message,true);}finally{controls.forEach(([el,disabled])=>el.disabled=disabled);button.innerHTML=old;delete form.dataset.saving;form.removeAttribute('aria-busy');}});}
  function drawer(title,html){const old=document.querySelector('#workspace-drawer');if(old)old.remove();const el=document.createElement('dialog');el.id='workspace-drawer';el.className='drawer';el.setAttribute('aria-labelledby','drawer-title');el.innerHTML=`<div class="drawer-head"><h2 id="drawer-title">${esc(title)}</h2><button class="close" aria-label="${B.h("ui.shared.fa0b7b3ac0","Close panel")}">×</button></div><div class="drawer-body">${html}</div>`;document.body.append(el);el.querySelector('.close').onclick=()=>el.close();el.addEventListener('click',e=>{if(e.target===el&&e.clientX<el.getBoundingClientRect().left)el.close();});el.showModal();return el;}
  let sidebarCleanup=()=>{};
