    sidebar.onkeydown=e=>{if(e.key==='Escape')closeSidebar();if(e.key==='Tab'&&sidebar.classList.contains('open')){const targets=[...sidebar.querySelectorAll('a[href],button:not([disabled])')].filter(el=>el.getClientRects().length);const first=targets[0],last=targets.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}};
    const desktop=matchMedia('(min-width:901px)');const onResize=()=>{if(!sidebar.isConnected){desktop.removeEventListener('change',onResize);return;}if(desktop.matches){sidebar.classList.remove('open');main.inert=false;backdrop.hidden=true;toggle.setAttribute('aria-expanded','false');}};desktop.addEventListener('change',onResize);sidebarCleanup=()=>desktop.removeEventListener('change',onResize);
